package ncasa.expense.infrastructure.outbox;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="outbox_messages") class JpaOutboxMessageEntity{@Id UUID id;@Column(name="aggregate_type",nullable=false)String aggregateType;@Column(name="aggregate_id",nullable=false)UUID aggregateId;@Column(name="event_type",nullable=false)String eventType;@Column(name="deduplication_key",nullable=false,unique=true)String deduplicationKey;@JdbcTypeCode(SqlTypes.JSON)@Column(nullable=false,columnDefinition="jsonb")String payload;@Column(name="occurred_at",nullable=false)Instant occurredAt;@Column(name="available_at",nullable=false)Instant availableAt;@Column(nullable=false)int attempts;@Column(nullable=false)String status;@Column(name="locked_at")Instant lockedAt;@Column(name="published_at")Instant publishedAt;@Column(name="last_error")String lastError;protected JpaOutboxMessageEntity(){}}
